def find_words(board, words):
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = w
    m, n = len(board), len(board[0])
    found = []

    def dfs(i, j, parent):
        ch = board[i][j]
        node = parent[ch]
        if "$" in node:
            found.append(node.pop("$"))
        board[i][j] = "#"
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            a, b = i + di, j + dj
            if 0 <= a < m and 0 <= b < n and board[a][b] in node:
                dfs(a, b, node)
        board[i][j] = ch
        if not node:
            del parent[ch]

    for i in range(m):
        for j in range(n):
            if board[i][j] in root:
                dfs(i, j, root)
    return sorted(found)

