function findWords(board, words) {
  const root = {};
  for (const w of words) {
    let node = root;
    for (const ch of w) {
      if (!node[ch]) node[ch] = {};
      node = node[ch];
    }
    node.$ = w;
  }
  const m = board.length, n = board[0].length;
  const found = [];
  function dfs(i, j, parent) {
    const ch = board[i][j];
    const node = parent[ch];
    if (node.$ !== undefined) {
      found.push(node.$);
      delete node.$;
    }
    board[i][j] = "#";
    for (const [di, dj] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const a = i + di, b = j + dj;
      if (a >= 0 && a < m && b >= 0 && b < n && node[board[a][b]]) dfs(a, b, node);
    }
    board[i][j] = ch;
    if (Object.keys(node).length === 0) delete parent[ch];
  }
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++)
      if (root[board[i][j]]) dfs(i, j, root);
  return found.sort();
}

