def run_median(ops):
    low = []   # max-heap (negated)
    high = []  # min-heap
    res = []
    for op in ops:
        if op[0] == "addNum":
            heapq.heappush(low, -op[1])
            heapq.heappush(high, -heapq.heappop(low))
            if len(high) > len(low):
                heapq.heappush(low, -heapq.heappop(high))
            res.append(None)
        else:
            if len(low) > len(high):
                res.append(-low[0])
            else:
                s = -low[0] + high[0]
                res.append(s // 2 if s % 2 == 0 else s / 2)
    return res

